      const { emoji, cleanName } = extractEmoji(dept.head.name)
      const headX = colX + (DEPT_WIDTH - LEADER_WIDTH) / 2
      rfNodes.push({
        id: dept.head.id,
        type: 'orgLeader',
        position: { x: headX, y: deptHeadsY },
        width: LEADER_WIDTH,
        height: LEADER_HEIGHT,
        data: {
          id: dept.head.id,
          name: cleanName,
          emoji,
          title: dept.head.title,
          model: dept.head.model,
          tier: dept.head.tier,
          phaseColor: dept.head.departmentColor || dept.head.phaseColor,
          description: dept.head.description,
          dimmed: false,
        } satisfies LeaderNodeData,
      })

      // Edge: connect from this head's actual `reportsTo` agent.
      // Falls back to Rex when reportsTo is missing or points outside the
      // currently-rendered set (so the card never floats orphaned).
      const reportsToId = dept.head.reportsTo
      const managerId = reportsToId && byId.has(reportsToId) ? reportsToId : rex?.id
      if (managerId && managerId !== dept.head.id) {
        rfEdges.push({
          id: `e-${managerId}-${dept.head.id}`,
          source: managerId,
          target: dept.head.id,
          type: 'smoothstep',
          style: { stroke: dept.color, strokeWidth: 2.5, opacity: 0.6 },
        })
      }
    }

    // Department column on Row 2.
    const deptNodeId = `dept-${dept.id}`
    rfNodes.push({
      id: deptNodeId,
      type: 'orgDept',
      position: { x: colX, y: deptColsY },
      width: DEPT_WIDTH,
      height: colHeight,
      data: {
        // Reuse phase* field names so OrgDepartmentNode renders unchanged.
        phase: dept.id,
        phaseLabel: dept.label,
        phaseColor: dept.color,
        members: visibleMembers,
        subDeptGroups: dept.subDeptGroups,
        width: DEPT_WIDTH,
        height: colHeight,
        dimmed: false,
      } satisfies DepartmentNodeData,
    })

    // Edge: dept head → its column.  If no head (Unassigned), connect Rex
    // directly to the column so it doesn't float orphaned.
    const edgeSource = deptHeadCardId || rex?.id
    if (edgeSource) {
      rfEdges.push({
        id: `e-${edgeSource}-${deptNodeId}`,
        source: edgeSource,
        target: deptNodeId,
        type: 'smoothstep',
        style: {
          stroke: dept.color,
          strokeWidth: 2,
          opacity: deptHeadCardId ? 0.55 : 0.35,
          strokeDasharray: deptHeadCardId ? undefined : '4 4',
        },
      })
    }
  })

  return { rfNodes, rfEdges }
}

// ── Leader Node Component ────────────────────────────────────────────────────

function OrgLeaderNode({ data, selected }: { data: LeaderNodeData; selected: boolean }) {
  const { onSelect, selectedId } = useContext(OrgSelectContext)
  const isSelected = selected || selectedId === data.id
  const badge = MODEL_BADGES[data.model]

  return (
    <div
      className="transition-opacity duration-200"
      style={{ opacity: data.dimmed ? 0.2 : 1 }}
    >
      <button
        onClick={(e) => {
          e.stopPropagation()
          onSelect(data.id)
        }}
        className={`relative rounded-2xl border-2 bg-surface shadow-lg transition-all duration-200 text-left block
          ${isSelected
            ? 'ring-2 ring-accent/40 ring-offset-2 ring-offset-bg border-accent'
            : 'border-border hover:border-accent/40 hover:shadow-xl'
          }`}
        style={{ width: LEADER_WIDTH, height: LEADER_HEIGHT }}
      >
        {/* Crown badge — only `tier === 'leadership'` agents reach this card,
            so the badge always reads LEADERSHIP. (Strict leader rule enforced
            in computeDepartmentLayout.) */}
        <div className="absolute -top-2.5 left-4 flex items-center gap-1 px-2 py-0.5 rounded-full bg-gradient-to-r from-amber-500 to-yellow-500 text-white shadow-sm">
          <Crown className="w-2.5 h-2.5" />
          <span className="text-[9px] font-bold uppercase tracking-wider">
            Leadership
          </span>
        </div>

        <div className="px-4 pt-4 pb-3 flex items-center gap-3 h-full">
          <AgentIcon name={data.name} uid={`leader-${data.id}`} size={48} global />
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-1.5">
              {data.emoji && <span className="text-base leading-none">{data.emoji}</span>}
              <span className="text-[15px] font-bold truncate">{data.name}</span>
